package main
import (
 "context"
 "encoding/json"
 "os"
 "path/filepath"
 "time"
 "github.com/lox/clyde/harness/gym"
 "github.com/lox/clyde/harness/rcon"
)
func main(){
 root:="/home/user/workspace/repo"
 t,e:=gym.LoadTask(root+"/gym/tasks/terrain-delivery.yaml");if e!=nil{panic(e)}
 t.Name="planner-terrain"
 os.MkdirAll(root+"/memory/slice9-planner",0755)
 p,e:=os.ReadFile(root+"/prompts/planner.md");if e!=nil{panic(e)}
 p=append(p,[]byte("\nIsolated curriculum session: on autonomous idle, pursue this one task: "+t.Goal.Description+" Keep the original delivery predicate through any player preemption. Do not author skills during this session.\n")...)
 os.WriteFile(root+"/memory/slice9-planner/planner.md",p,0644)
 r:=gym.Runner{Root:root,Agent:"bash /tmp/clyde9-planner-agent",Username:"clyde",Timeout:300*time.Second,RunDir:"/tmp/clyde9-planner",Log:os.Stderr}
 ctx,cancel:=context.WithCancel(context.Background());defer cancel()
 done:=make(chan struct{})
 go func(){defer close(done)
  for {if _,e:=os.Stat(filepath.Join(r.RunDir,t.Name,"ready"));e==nil{break};time.Sleep(100*time.Millisecond)}
  conn,e:=rcon.Dial(ctx,"127.0.0.1:"+os.Getenv("GYM_RCON_PORT"),gym.RCONPassword());if e!=nil{panic(e)};defer conn.Close()
  f,e:=os.Create(filepath.Join(r.RunDir,t.Name,"player-inventory.jsonl"));if e!=nil{panic(e)};defer f.Close()
  tick:=time.NewTicker(500*time.Millisecond);defer tick.Stop()
  for {select{case <-ctx.Done():return;case <-tick.C:
   out,e:=conn.Exec("execute if items entity clyde container.* minecraft:stick")
   json.NewEncoder(f).Encode(map[string]any{"ts":time.Now().UnixMilli(),"reply":out,"error":e})
  }}
 }()
 res:=r.Run(ctx,t,0);cancel();<-done
 json.NewEncoder(os.Stdout).Encode(res)
}

