import fs from 'node:fs'
import path from 'node:path'
import mineflayer from '/home/user/workspace/repo/gym/agents/node_modules/mineflayer/index.js'
const dir=path.dirname(process.env.GYM_TASK)
const write=(file,v)=>fs.appendFileSync(path.join(dir,file),JSON.stringify({ts:Date.now(),...v})+'\n')
const bot=mineflayer.createBot({host:process.env.MC_HOST,port:Number(process.env.MC_PORT),username:'Alex',auth:'offline',version:'26.1'})
let sent=false,seq=0,polling=false
bot.on('chat',(username,message)=>write('player-chat.jsonl',{username,message}))
bot.on('error',err=>write('player-chat.jsonl',{error:err.message}))
bot.once('spawn',()=>{
 setInterval(async()=>{
  if(polling)return;polling=true
  try{
   const events=await (await fetch('http://127.0.0.1:7789/events?since='+seq)).json()
   for(const event of events.events||[])write('body-events.jsonl',{event})
   seq=events.latestSeq??seq
   const c=await (await fetch('http://127.0.0.1:7789/state')).json()
   if(!sent&&c.action&&(c.inventory?.items||[]).some(i=>i.name==='birch_log'&&i.count>=2)){
    sent=true
    const message='Clyde, craft four sticks and keep them in your inventory, then resume your work.'
    write('player-chat.jsonl',{sent:true,message})
    bot.chat(message)
   }
  }catch(error){write('player-chat.jsonl',{error:String(error)})}finally{polling=false}
 },200)
})
process.on('SIGTERM',()=>{bot.quit();process.exit(0)})

