#!/usr/bin/env bash
set -euo pipefail
root=/home/user/workspace/repo
export BODY_LISTEN_HOST=127.0.0.1 BODY_LISTEN_PORT=7789
base=http://127.0.0.1:7789
dir=$(dirname "$GYM_TASK")
(cd "$root/body" && exec node --import tsx src/index.ts) &
body=$!
trap 'curl -fsS "$base/events" > "$dir/events.json" || true; kill "$body" 2>/dev/null || true' EXIT
trap 'exit 143' TERM
for _ in $(seq 1 60); do curl -fsS -o /dev/null "$base/state" 2>/dev/null && break || sleep 1; done
until [ -e "$GYM_READY" ]; do sleep 0.2; done
"$root/gym/.bin/judge" --body "$base" --log "$dir/judge.jsonl" > "$dir/interrupts.jsonl" &
node --input-type=module <<'JS'
const code = process.env.PROBE_MODE === 'idle' ? 'await sleep(30000)' : `
await bot.equip(bot.inventory.items().find(i=>i.name==='oak_planks'),'hand');
for(let z=149;z<=151;z++)for(let x=-310;x<=-308;x++){
 if(x===-309&&z===150)continue;
 const ref=bot.blockAt(new Vec3(x,78,z));
 await bot.placeBlock(ref,new Vec3(0,1,0));
 await sleep(2000);
}`;
const r=await fetch('http://127.0.0.1:7789/action',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({type:'eval',code,timeoutMs:30000})});
console.log(await r.text());
JS
while :; do
  if jq -se 'any(.reason == "stuck" or .reason == "danger")' "$dir/interrupts.jsonl" >/dev/null; then
    curl -fsS -X POST "$base/stop"
    curl -fsS "$base/state" > "$dir/final-card.json"
    exit 2
  fi
  curl -fsS "$base/state" >> "$dir/cards.jsonl"
  printf '\n' >> "$dir/cards.jsonl"
  sleep 0.5
done

