package main

import (
	"context"
	"encoding/json"
	"github.com/lox/clyde/harness/gym"
	"os"
	"time"
)

func main() {
	root := "/home/user/workspace/repo"
	t, err := gym.LoadTask(root + "/gym/tasks/terrain-delivery.yaml")
	if err != nil {
		panic(err)
	}
	t.Name = "planner-final-terrain"
	os.MkdirAll(root+"/memory/slice9-planner-final", 0755)
	p, err := os.ReadFile(root + "/prompts/planner.md")
	if err != nil {
		panic(err)
	}
	p = append(p, []byte("\nIsolated curriculum session: on autonomous idle, pursue this one task: "+t.Goal.Description+" Keep the original delivery predicate through any player preemption. Do not author skills during this session.\n")...)
	os.WriteFile(root+"/memory/slice9-planner-final/planner.md", p, 0644)
	r := gym.Runner{Root: root, Agent: "bash /tmp/clyde9-planner-final-agent", Username: "clyde", Timeout: 300 * time.Second, RunDir: "/tmp/clyde9-planner-final", Log: os.Stderr}
	res := r.Run(context.Background(), t, 0)
	f, err := os.Create("/tmp/clyde9-planner-final/result.json")
	if err != nil {
		panic(err)
	}
	defer f.Close()
	json.NewEncoder(f).Encode(res)
	json.NewEncoder(os.Stdout).Encode(res)
}

